"""Cold serial replay; expected files are read, never generated by this runner."""
import argparse
import datetime
import hashlib
import json
import os
import resource
import subprocess
import sys
import time
from pathlib import Path

def need(test, message):
    if not test:
        raise ValueError(message)

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('--work', required=True)
    args = parser.parse_args()
    here = Path(__file__).absolute().parent
    work = Path(args.work).absolute(); work.mkdir(parents=True, exist_ok=True)
    frozen_before = (here/'expected.json').exists() and (here/'BRIDGE.json').exists()
    need(frozen_before, 'pre-existing frozen mathematical records required')
    expected = json.loads((here/'expected.json').read_text())
    bridge_bytes = (here/'BRIDGE.json').read_bytes()
    need(hashlib.sha256(bridge_bytes).hexdigest() == expected['bridge_sha256'], 'frozen bridge bytes differ')
    bridge = json.loads(bridge_bytes)
    environment = dict(os.environ)
    for name in ('OMP_NUM_THREADS', 'OPENBLAS_NUM_THREADS', 'MKL_NUM_THREADS', 'NUMEXPR_NUM_THREADS'):
        environment[name] = '1'
    python = [sys.executable] + (['-O'] if sys.flags.optimize else [])
    receipts = []
    start = time.monotonic()
    def run(label, arguments):
        command = python + [str(here/arguments[0])] + [str(p) for p in arguments[1:]]
        clock = time.monotonic()
        result = subprocess.run(command, env=environment, stdout=subprocess.PIPE, stderr=subprocess.PIPE,
                                text=True, timeout=60)
        (work/(label+'.stdout')).write_text(result.stdout)
        (work/(label+'.stderr')).write_text(result.stderr)
        receipt = dict(label=label, command=command, exit_code=result.returncode, seconds=time.monotonic()-clock)
        receipts.append(receipt)
        (work/'receipts.json').write_text(json.dumps(receipts, sort_keys=True, indent=2)+'\n')
        need(result.returncode == 0, 'INCOMPLETE failed stage '+label)
        print(json.dumps(dict(stage=label, seconds=receipt['seconds'])), flush=True)
        return result.stdout
    for first in range(0, 360, 30):
        run(f'primary-{first:03d}', ['produce.py', '--fixtures', here/'fixtures.json', '--work', work/'primary',
                                    '--first', first, '--finish', first+30])
    run('point-dfs', ['verify.py', '--fixtures', here/'fixtures.json', '--primary-work', work/'primary',
                      '--output', work/'point-dfs.json'])
    checked = json.loads((work/'point-dfs.json').read_text())
    need(checked['status'] == 'COMPLETE_INDEPENDENT_POINT_DFS' and
         checked['records_sha256'] == expected['checker_records_sha256'] and
         checked['domain_sha256'] == expected['domain_sha256'], 'complete frozen census comparison failed')
    actual = [dict(product_index=row['product_index'], first=row['first'], second=row['second'], **positive)
              for row in checked['records'] for positive in row['positives']]
    need(actual == bridge['raw_positive_maps'], 'complete literal34-map inventory differs')
    bridge_result = json.loads(run('literal-bridge', ['check_bridge.py', '--bridge', here/'BRIDGE.json',
        '--fixtures', here/'fixtures.json', '--seeds', here/'seed_certificates.json']).strip())
    controls = json.loads(run('controls', ['controls.py', '--primary-work', work/'primary', '--work', work/'controls']).strip())
    stable = dict(status='COMPLETE_LOCAL_TWO_INTERFACE_UPPER64', expected_frozen_before_replay=frozen_before,
                  checker_records_sha256=checked['records_sha256'], domain_sha256=checked['domain_sha256'],
                  bridge_sha256=expected['bridge_sha256'], products=360, raw_compatible_maps=len(actual),
                  bridge=bridge_result, controls=controls,
                  scope='Only explicit local paired saturated-star hypotheses; no hub multiplicity, global degree profile or involution.')
    (work/'RESULT.json').write_text(json.dumps(stable, sort_keys=True, indent=2)+'\n')
    metadata = dict(agent='six-code-3', role='researcher', python=sys.version, optimized=bool(sys.flags.optimize),
                    finished_utc=datetime.datetime.now(datetime.timezone.utc).isoformat(), seconds=time.monotonic()-start,
                    peak_child_rss_kib=resource.getrusage(resource.RUSAGE_CHILDREN).ru_maxrss, threads=1,
                    scope='Unchanged1CPU2GiB; one sequential CPU-intensive job',
                    guards='10s/product;200000 point-DFS states/product;60s subprocess',
                    source_sha256={p.name:hashlib.sha256(p.read_bytes()).hexdigest() for p in here.iterdir() if p.is_file()},
                    receipts=receipts)
    (work/'METADATA.json').write_text(json.dumps(metadata, sort_keys=True, indent=2)+'\n')
    print(json.dumps(stable, sort_keys=True), flush=True)

if __name__ == '__main__':
    main()
